import test from 'node:test';
import assert from 'node:assert/strict';
import { page,clock,microtasks } from './support.js';
import { bootstrap } from '../src/runtime/browser.js';
import { defaults } from '../src/runtime/preferences.js';

// Independent observed-DOM fixtures. Local history is generated by the actual
// application, not forged storage; play/ended are controlled synthetic media.
async function setup({history='restored',credit=true,taskCredit=false,kinds=['video'],delay=0,prepare=()=>{}}={}) {
  const f=page(kinds),time=clock(),media=f.players[0];let calls=0,paused=true,ended=false;
  Object.defineProperties(media,{paused:{get:()=>paused},ended:{get:()=>ended}});
  media.play=()=>{calls++;paused=false;return Promise.resolve();};media.pause=()=>{paused=true;};
  f.dom.window.localStorage.setItem('xxt.state.v1',JSON.stringify({version:1,settings:{...defaults,delays:delay>0,minMs:delay,maxMs:delay},stopped:false,count:0,seen:[],restUntil:0}));
  let app;
  if(history!=='fresh'){
    app=bootstrap(f.document,{clock:time,ui:false});time.advance(0);await microtasks();assert.equal(calls,1);
    ended=true;media.dispatchEvent(new f.dom.window.Event('ended'));time.advance(0);await microtasks();
    assert.equal(app.view().taskState,kinds.length===1?'WAITING_PLATFORM':'UNSUPPORTED');
    if(history==='restored')app.dispose();
  }
  if(credit)f.markLesson();
  if(taskCredit)f.owners[0].parentElement.querySelector('.ans-job-icon').classList.add('ans-job-finished');
  prepare(f);
  if(history!=='current')app=bootstrap(f.document,{clock:time,ui:false});
  return {...f,time,app,calls:()=>calls,async tick(ms=500){time.advance(ms);await microtasks();},close(){app.dispose();f.dom.window.close();}};
}
function destination(f) {
  let clicks=0,plays=0;const target=f.document.querySelector('#unit-0-1');
  target.onclick=()=>{
    clicks++;f.document.querySelector('.posCatalog_active').classList.remove('posCatalog_active');target.classList.add('posCatalog_active');
    f.root.body.innerHTML='<section class="ans-attach-ct"><span class="ans-job-icon"></span><iframe id="destination" class="ans-attach-online ans-insertvideo-online" data=\'{"objectid":"destination-content"}\'></iframe></section>';
    const inner=f.root.querySelector('iframe').contentDocument;inner.body.innerHTML='<video id="video_html5_api" src="https://invalid.example/destination"></video>';
    const next=inner.querySelector('video');let paused=true;Object.defineProperty(next,'paused',{get:()=>paused});next.play=()=>{plays++;paused=false;return Promise.resolve();};next.pause=()=>{paused=true;};
  };
  return {target,clicks:()=>clicks,plays:()=>plays};
}

for(const history of ['fresh','restored','current'])test(`${history} whole-lesson credit without own task marker navigates once and independently acknowledges destination`,async()=>{
  const f=await setup({history}),next=destination(f);
  assert.equal(f.owners[0].parentElement.querySelector('.ans-job-finished'),null);
  assert.equal(f.app.view().platformConfirmed,true);
  if(history==='restored')assert.equal(f.app.view().taskState,'RESTORED_WAITING_PLATFORM');
  await f.tick();assert.equal(next.clicks(),1);assert.equal(f.document.querySelector('.posCatalog_active'),next.target);assert.equal(f.app.view().platformConfirmed,false);
  await f.tick();await f.tick(0);assert.equal(next.plays(),1);assert.equal(f.app.view().taskState,'RUNNING');assert.equal(f.app.view().localDone,false);
  assert.equal(f.calls(),history==='fresh'?0:1);assert.equal(next.clicks(),1);f.close();
});

test('restored history with both task and lesson credit uses the same native handoff',async()=>{
  const f=await setup({taskCredit:true}),next=destination(f);await f.tick();await f.tick();
  assert.equal(next.clicks(),1);assert.equal(next.plays(),1);assert.equal(f.calls(),1);assert.equal(f.document.querySelector('.posCatalog_active'),next.target);f.close();
});

test('restored local end alone, or lesson text without a real marker, never authorizes navigation',async()=>{
  const f=await setup({credit:false}),next=destination(f);f.root.body.append('任务点已完成');await f.tick(2000);
  assert.equal(f.app.view().platformConfirmed,false);assert.equal(f.app.view().taskState,'RESTORED_WAITING_PLATFORM');assert.equal(next.clicks(),0);assert.equal(f.calls(),1);f.close();
});

test('positive lesson credit cannot override contradictory task counts or explicit incomplete attachment evidence',async()=>{
  for(const contradictory of [true,false]){
    const f=await setup({taskCredit:contradictory,prepare(f){f.owners[0].parentElement.insertAdjacentHTML('beforeend','<input class="jobUnfinishCount" value="1">');}}),next=destination(f);
    await f.tick(2000);assert.equal(next.clicks(),0);assert.equal(f.calls(),1);f.close();
  }
});

test('positive lesson credit still blocks unknown, assessment, verification and competing active media',async()=>{
  for(const hazard of ['unknown','assessment','verification','active']){
    const f=await setup({kinds:hazard==='unknown'?['video','unknown']:['video'],prepare(f){
      if(hazard==='assessment')f.document.querySelector('.prev_title').title='必须完成测试';
      if(hazard==='verification')f.root.body.insertAdjacentHTML('beforeend','<form>验证码<input name="captcha"></form>');
      if(hazard==='active'){const audio=f.root.createElement('audio');audio.id='auditionAudio';Object.defineProperty(audio,'paused',{value:false});f.root.body.append(audio);}
    }}),next=destination(f);await f.tick(2000);assert.equal(next.clicks(),0,hazard);assert.equal(f.calls(),1,hazard);f.close();
  }
});

test('delayed prior-credit permit cannot act on stale lesson identity or a newly restricted catalog target',async()=>{
  for(const change of ['identity','catalog']){
    const f=await setup({delay:1000}),next=destination(f);await f.tick();assert.equal(f.app.view().delayed,true);
    if(change==='identity')f.dom.window.history.replaceState(null,'','?courseid=different-synthetic-course');
    else next.target.setAttribute('aria-disabled','true');
    await f.tick();await f.tick(2500);for(const callback of [...f.time.cancelled])callback();await microtasks();
    assert.equal(next.clicks(),0,change);assert.equal(f.calls(),1,change);f.close();
  }
});

test('Stop during restored prior-credit delay cancels activation and reload preserves Stop',async()=>{
  const f=await setup({delay:1000}),next=destination(f);await f.tick();assert.equal(f.app.view().delayed,true);f.app.stop();await f.tick(3000);
  for(const callback of [...f.time.cancelled])callback();await microtasks();assert.equal(next.clicks(),0);assert.equal(f.calls(),1);
  f.app.dispose();const app=bootstrap(f.document,{clock:f.time,ui:false});await f.tick(1000);assert.match(app.view().message,/停止/);assert.equal(next.clicks(),0);app.dispose();f.close();
});
